// Photos live inside the synced household record, so keep each one small. Safari cannot encode WebP (it silently
// returns a large PNG), so JPEG is the portable format; step size and quality down until it fits.
const PHOTO_LIMIT=110000,large=photo=>typeof photo==='string'&&photo.startsWith('data:')&&photo.length>PHOTO_LIMIT*1.4;
async function compressPhoto(source){const blob=typeof source==='string'?await (await fetch(source)).blob():source;let bitmap;try{bitmap=await createImageBitmap(blob)}catch{throw new Error('This image format cannot be read here. Choose a JPG or PNG photo.')}let result='';for(const [size,quality]of [[512,.82],[512,.7],[420,.68],[360,.62],[300,.55]]){const ratio=Math.min(1,size/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const context=canvas.getContext('2d');context.fillStyle='#fffaf0';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);result=canvas.toDataURL('image/jpeg',quality);if(result.length<=PHOTO_LIMIT)break}bitmap.close?.();return result}
